2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.rest.validation.E164Telephone;
13	import org.springframework.samples.petclinic.util.AddressNormalizer;
14	
15	import java.util.Collection;
16	import java.util.List;
17	import java.util.Map;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
26	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
27	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
28	    @Mapping(target = "membershipTier", expression = "java(formatMembershipTier(owner))")
29	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
30	    OwnerDto toOwnerDto(Owner owner);
31	
32	    /**
33	     * Known city-to-region mappings. Keyed by the exact city name, the canonical region
34	     * string is returned for a listed city and {@code "UNKNOWN"} for anything else.
35	     */
36	    Map<String, String> CITY_REGIONS = Map.of(
37	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
38	
39	    /**
40	     * Derive an owner's locality from its city using the fixed {@link #CITY_REGIONS}
41	     * city-to-region table, returning the canonical region string or {@code "UNKNOWN"}
42	     * when the city is {@code null} or not present in the table.
43	     */
44	    default String formatLocality(Owner owner) {
45	        if (owner == null) {
46	            return null;
47	        }
48	        return CITY_REGIONS.getOrDefault(owner.getCity(), "UNKNOWN");
49	    }
50	
51	    /**
52	     * Determine an owner's membership tier: {@code "SILVER"} when the owner has no namesakes
53	     * (its {@code namesakeCount} is {@code 0}) and an email address is present, otherwise
54	     * {@code "BRONZE"}. A null or absent namesake count is treated as not being zero, so the
55	     * tier only reaches SILVER for an explicitly unique owner with an email.
56	     */
57	    default String formatMembershipTier(Owner owner) {
58	        if (owner == null) {
59	            return null;
60	        }
61	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
62	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
63	        return uniqueName && hasEmail ? "SILVER" : "BRONZE";
64	    }
65	
66	    /**
67	     * Format an owner's membership number as {@code "<customerCode>-M<YY>"}, where {@code YY}
68	     * is the last two digits of the registration date year (e.g. {@code "TOW-SMI-0007-M26"}).
69	     * Returns {@code null} when either the customer code or registration date is absent, since
70	     * the number cannot be derived without both.
71	     */
72	    default String formatMembershipNumber(Owner owner) {
73	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
74	            return null;
75	        }
76	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
77	    }
78	
79	    /**
80	     * Format an owner's name as {@code "LastName, FirstName"} from the stored names.
81	     */
82	    default String formatDisplayName(Owner owner) {
83	        if (owner == null) {
84	            return null;
85	        }
86	        return owner.getLastName() + ", " + owner.getFirstName();
87	    }
88	
89	    /**
90	     * Format an owner's initials as the upper-cased first letters of the first and last
91	     * names, dot-separated with a trailing dot, e.g. {@code "J.S."}.
92	     */
93	    default String formatInitials(Owner owner) {
94	        if (owner == null) {
95	            return null;
96	        }
97	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
98	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
99	    }
100	
101	    Owner toOwner(OwnerDto ownerDto);
102	
103	    @Mapping(target = "id", ignore = true)
104	    @Mapping(target = "pets", ignore = true)
105	    @Mapping(target = "householdId", ignore = true)
106	    @Mapping(target = "namesakeCount", ignore = true)
107	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
108	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
109	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
110	    Owner toOwner(OwnerFieldsDto ownerDto);
111	
112	    /**
113	     * Normalize a postal address for storage into its canonical form (see
114	     * {@link AddressNormalizer}), so it is persisted and returned the same way regardless of
115	     * the formatting supplied by the caller. {@code @Named} keeps this out of MapStruct's
116	     * automatic method selection, so it only runs where a mapping explicitly references it via
117	     * {@code qualifiedByName}.
118	     */
119	    @Named("normalizeAddress")
120	    default String normalizeAddress(String address) {
121	        return AddressNormalizer.normalize(address);
122	    }
123	
124	    /**
125	     * Normalize a telephone number for storage into E.164 form (see {@link E164Telephone}).
126	     * The requirement that a valid E.164 number can be formed is enforced separately by
127	     * {@code TelephoneValidation}, so for already-validated input this returns the E.164
128	     * string; it is idempotent, so re-normalizing a stored value yields the same value.
129	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
130	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
131	     */
132	    @Named("normalizeTelephone")
133	    default String normalizeTelephone(String telephone) {
134	        return E164Telephone.normalize(telephone);
135	    }
136	
137	    /**
138	     * Normalize an email address for storage by lower-casing it, so it is persisted and
139	     * returned in a canonical form regardless of the casing supplied by the caller.
140	     * Syntactic validity is enforced separately by the {@code @Email} constraint on the DTO.
141	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
142	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
143	     */
144	    @Named("normalizeEmail")
145	    default String normalizeEmail(String email) {
146	        return email == null ? null : email.toLowerCase();
147	    }
148	
149	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
150	
151	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
152	
153	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
154	        OwnerPageDto ownerPageDto = new OwnerPageDto();
155	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
156	        ownerPageDto.setPage(ownerPage.getNumber());
157	        ownerPageDto.setSize(ownerPage.getSize());
158	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
159	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
160	        return ownerPageDto;
161	    }
162	}
